/**
 * The words of a text box, set in a font and cut to a subset of it, as the main process keeps
 * them for an open document (B2-28, ADR 0018): named by this number in edits, as a picture of a
 * stamp is. The page asks for one with `prepare_text_box` and then puts it in a box with
 * `Edit::AddTextBox`; undo, redo and the crash recovery journal make the edit again from what is
 * kept, without the font file.
 */
export type TextBoxModelId = number;

/**
 * Arguments of `prepare_text_box` (B2-28): the words and the font to set them in, never a path.
 * Any other field is rejected.
 */
export type PrepareTextBoxArgs = { doc: DocumentId, 
/**
 * Not empty, at most `MAX_TEXT_BOX_BYTES`; lines are broken at `\n`.
 */
text: string, 
/**
 * A font of the list `get_fonts` gave.
 */
font: FontId, };

/**
 * What `prepare_text_box` tells of the words it prepared (B2-28).
 */
export type PreparedTextBox = { 
/**
 * The number to put them in a box with.
 */
model: TextBoxModelId, 
/**
 * The font's licence lets a document with it be viewed and printed only: the page says so.
 */
viewOnly: boolean, };

/**
 * What a text box says of itself (B2-29), from the page's worker: to fill in the dialog that
 * changes it. The font is the name Windows lists it by; it may not be on this computer any more
 * (the box is still shown and printed, and moved and resized, but other words or another font
 * need a font that is).
 */
export type TextBoxInfo = { text: string, font: string, style: TextBoxStyle, 
/**
 * The font's licence lets a document with it be viewed and printed only.
 */
viewOnly: boolean, 
/**
 * The words do not fit the box: what is below is cut off.
 */
overflow: boolean, };

/**
 * Kinds of active content or remote references found in a document (MVP-11).
 * None of them is ever executed or followed.
 */
export type FindingKind = "javaScript" | "openAction" | "additionalActions" | "launch" | "submitForm" | "importData" | "remoteGoTo" | "embeddedGoTo" | "remoteFileSpec" | "uncReference" | "xfa" | "richMedia" | "embeddedFile";

export type SecurityFinding = { kind: FindingKind, count: number, };

/**
 * Result of the worker's active-content scan. Each kind appears at most once.
 */
export type SecurityReport = { findings: Array<SecurityFinding>, 
/**
 * False when the scan hit its time or size budget before finishing.
 */
scanComplete: boolean, };

/**
 * What the document's author allows (MVP-19). An encrypted PDF can forbid copying its text and
 * printing it; the app obeys, as Adobe Acrobat does. An unencrypted document allows everything.
 */
export type DocumentPermissions = { copy: boolean, print: boolean, 
/**
 * Printing at full quality; without it only a low-resolution image is printed.
 */
printHighQuality: boolean, 
/**
 * Changing the document (`/P` bit 4).
 */
modify: boolean, 
/**
 * Inserting, deleting and rotating pages (`/P` bit 11, or bit 4 before revision 3).
 */
assemble: boolean, 
/**
 * Adding, changing and removing annotations (`/P` bit 6, B2-07).
 */
annotate: boolean, 
/**
 * Filling in form fields (`/P` bit 9, or bit 6 which covers annotations and forms, B2-09).
 */
fillForms: boolean, };

/**
 * Changes to a file that an earlier run of the app made but neither saved nor discarded: it
 * ended first (B2-13, ADR 0013). They are kept in the app's local data folder until the user
 * answers.
 */
export type Recovery = "none" | "available" | "partial" | "lost" | "stale";

/**
 * The signatures of an open document, as far as they could be looked at (B2-14, ADR 0014).
 */
export type SignatureReport = { 
/**
 * One entry for each signature field that has a signature, in the order of the form.
 */
signatures: Array<SignatureInfo>, 
/**
 * The document has more signature fields than were looked at (`MAX_SIGNATURES`).
 */
truncated: boolean, };

/**
 * What verifying one signature of an open document found (B2-14, ADR 0014). It is checked
 * offline: that a signature holds says the signed bytes are as the signer left them, never that
 * the signer is who they say (see `signer_trusted`), and nothing is asked of any server.
 */
export type SignatureInfo = { status: SignatureStatus, 
/**
 * The signer's certificate chains to a root Windows trusts, with what Windows has on this
 * computer (nothing is fetched; whether it was revoked is not checked). Only meaningful for
 * a signature that holds (`valid`, `changedAfterSigning`).
 */
signerTrusted: boolean, 
/**
 * Why the signature could not be verified (`unverifiable`).
 */
reason: UnverifiableReason | null, 
/**
 * The signature field's name, as the file gives it; display only.
 */
fieldName: string | null, 
/**
 * Who signed, as the certificate names them. Only for a signature that holds.
 */
signer: string | null, 
/**
 * When the signer says they signed, as text ("2026-09-24 12:00:00 UTC+08:00"). Only the
 * signer's own claim: nothing vouches for the time (there is no time stamp, RFC 3161).
 */
claimedTime: string | null, 
/**
 * A signature that certifies the document says what may still be changed in it (DocMDP).
 */
certification: Certification | null, };

/**
 * Whether a signature holds (B2-14).
 */
export type SignatureStatus = "valid" | "changedAfterSigning" | "invalid" | "unverifiable";

/**
 * Why a signature could not be verified (B2-14).
 */
export type UnverifiableReason = "unsupportedFormat" | "unsupportedAlgorithm" | "tooLarge" | "notAvailable";

/**
 * What a certifying signature allows to be changed after it (DocMDP, B2-14).
 */
export type Certification = "noChanges" | "fillForms" | "fillFormsAndAnnotate";

/**
 * An open document as the frontend sees it.
 */
export type DocumentInfo = { doc: DocumentId, 
/**
 * File name for display only (no directory components).
 */
displayName: string, 
/**
 * One entry per page; the page count is `pages.length`.
 */
pages: Array<PageSize>, hasOutline: boolean, 
/**
 * The document has a form (fields to fill in, B2-09), which flattening has not turned into
 * page content.
 */
hasForm: boolean, security: SecurityReport, permissions: DocumentPermissions, 
/**
 * Changed since it was opened or last saved (B2-02): the file does not have the changes yet.
 */
unsaved: boolean, 
/**
 * Encrypted (MVP-16): it has no privacy export (B2-03).
 */
encrypted: boolean, 
/**
 * An edit made since the file was last written can be undone (B2-05, ADR 0013). A document
 * opened with a password asks for it again to undo: it is not kept (MVP-16, #94).
 */
canUndo: boolean, 
/**
 * An edit that was undone can be made again.
 */
canRedo: boolean, 
/**
 * Unsaved changes an earlier run of the app left for this file (B2-13, ADR 0013).
 */
recovery: Recovery, 
/**
 * A password is remembered for this file (B2-25, ADR 0017): it can be forgotten.
 */
passwordRemembered: boolean, 
/**
 * The file was opened with the remembered password, without the user typing one.
 */
passwordRecalled: boolean, 
/**
 * The file is marked as sensitive (B3-05, ADR 0004): it carries the app's document identifier
 * (ADR 0010). Text copied from it stays out of Windows' clipboard history and cloud
 * clipboard, and the file is not on the recent files list.
 */
sensitive: boolean, };

/**
 * Arguments of the `render_page` command.
 */
export type RenderPageArgs = { request: RequestId, doc: DocumentId, pageIndex: number, 
/**
 * 1.0 = one PDF point per pixel. Includes the device pixel ratio.
 */
scale: number, rotation: Rotation, };

/**
 * Actions that are recognised but never performed.
 */
export type BlockedAction = "launch" | "remoteGoTo" | "embeddedGoTo" | "javaScript" | "submitForm" | "importData" | "localFile" | "networkShare" | "other";

/**
 * Where a link or outline item points.
 *
 * Serialized with a `kind` tag in JSON (for the frontend), but externally tagged in binary
 * formats: postcard, used between the main process and the worker, cannot decode internally
 * tagged enums. See [`link_target_serde`].
 */
export type LinkTarget = { "kind": "page", pageIndex: number, x: number | null, y: number | null, } | { "kind": "uri", uri: string, } | { "kind": "blocked", action: BlockedAction, target: string | null, };

/**
 * Identifies a link reported by the worker, so the main process can look it up later
 * instead of trusting a URI string sent back by the frontend.
 */
export type LinkId = { pageIndex: number, index: number, };

export type PageLink = { id: LinkId, rect: Rect, target: LinkTarget, };

/**
 * Arguments of `describe_link` and `open_link` (MVP-12): a link the worker reported, by id.
 * There is deliberately no field for a URI; any other field is rejected.
 */
export type LinkArgs = { doc: DocumentId, link: LinkId, };

/**
 * Arguments of `describe_outline_link` and `open_outline_link` (#49): an outline item by its
 * position in the outline the worker reported (`OutlineResult::items`), never a URI.
 */
export type OutlineLinkArgs = { doc: DocumentId, item: number, };

/**
 * What the confirmation shows about a web link before it is opened (MVP-12).
 */
export type LinkPreview = { 
/**
 * The URI exactly as the PDF has it; the frontend writes out its hidden characters.
 */
uri: string, 
/**
 * What the system is given when the user opens it: ASCII only, the host in punycode and
 * everything else percent-encoded. Also what "copy link" copies.
 */
opens: string, 
/**
 * The site the browser will contact (for `mailto`, the mail domain), as it reads.
 */
host: string | null, 
/**
 * The host's ASCII (punycode) form when it differs from `host`: an internationalised
 * name, which may imitate another one.
 */
asciiHost: string | null, };

/**
 * One outline entry, in pre-order; `depth` 0 is the top level.
 */
export type OutlineItem = { title: string, depth: number, target: LinkTarget | null, };

export type OutlineResult = { items: Array<OutlineItem>, 
/**
 * True when the outline exceeded the item or depth limit and was cut short.
 */
truncated: boolean, };

/**
 * Arguments of the `search` command. Results arrive on a Tauri channel as [`SearchEvent`]s.
 */
export type SearchArgs = { request: RequestId, doc: DocumentId, query: string, caseSensitive: boolean, };

export type SearchHit = { quads: Array<Quad>, };

export type SearchEvent = { "kind": "hits", pageIndex: number, hits: Array<SearchHit>, } | { "kind": "progress", pagesSearched: number, } | { "kind": "done", totalHits: number, truncated: boolean, noTextLayer: boolean, };

/**
 * One page's text for selecting and copying (MVP-15): its lines in reading order, from the
 * same text layer that search looks at.
 */
export type PageText = { lines: Array<TextLine>, 
/**
 * The page had more than `LIMITS.maxPageTextChars` characters; the rest was left out.
 */
truncated: boolean, 
/**
 * The page has no text of its own: this was recognised from its picture (OCR, B2-10), and
 * may be wrong.
 */
recognised: boolean, };

/**
 * A line of text in page space. Its characters sit side by side from the quad's `ul` towards
 * `ur` (the writing direction, which need not be horizontal), and the line reaches from `ul`
 * to `ll` across.
 */
export type TextLine = { 
/**
 * Plain text: every kind of whitespace is a space, and there are no control or invisible
 * formatting characters (they could hide or reorder what is pasted).
 */
text: string, quad: Quad, 
/**
 * Where each character of `text` (a Unicode scalar value) starts, in points from `ul`
 * towards `ur`, then where the last one ends: one more value than characters, never
 * decreasing.
 */
edges: Array<number>, };

/**
 * Error codes the frontend maps to localized messages.
 */
export type ErrorCode = "unknownDocument" | "invalidArgument" | "cancelled" | "notPdf" | "corrupted" | "encrypted" | "unsupportedEncryption" | "notAllowed" | "unreadable" | "tooLarge" | "limitExceeded" | "workerCrashed" | "workerTimeout" | "protocolViolation" | "readOnly" | "diskFull" | "fileInUse" | "changedOnDisk" | "unwritable" | "signed" | "fontUnavailable" | "fontInvalid" | "fontNotTrueType" | "fontVariable" | "fontColour" | "fontNotEmbeddable" | "fontMissingGlyphs" | "textNotSupported" | "networkFailed" | "credentialsUnavailable" | "pictureNotCleaned" | "internal";

/**
 * Rejection value of every command. `message` is for logs and must not contain paths or
 * document content; the UI shows a localized text chosen by `code`.
 */
export type IpcError = { code: ErrorCode, message: string, };

/**
 * Pushed by the main process on the channel passed to `subscribe_open_events`, for documents
 * opened from the dialog, by drag and drop, from the command line or from a second launch of
 * the app. Every file gets its own tab (MVP-14): `Opening` adds it, then `Opened` or `Failed`
 * says how it went.
 */
export type OpenEvent = { "kind": "dragHover", active: boolean, } | { "kind": "opening", tab: TabId, displayName: string, } | { "kind": "opened", tab: TabId, info: DocumentInfo, } | { "kind": "passwordNeeded", tab: TabId, displayName: string, wrong: boolean, canRemember: boolean, rememberedFailed: boolean, } | { "kind": "failed", tab: TabId, displayName: string, error: IpcError, } | { "kind": "tabLimit", ignoredFiles: number, } | { "kind": "closeRequested", tabs: Array<TabId>, } | { "kind": "ocr", tab: TabId, progress: OcrProgress, } | { "kind": "ocrPage", tab: TabId, doc: DocumentId, pageIndex: number, };

/**
 * The kind of file an annotation summary is written as (B3-18).
 */
export type AnnotationSummaryFormat = "text" | "markdown";

/**
 * Writes a summary of the annotations of document `doc` (B3-18) as a UTF-8 file of `format`
 * where the user says in the system's save dialog. The main process makes the file; no text of
 * the document passes through the page.
 */
export type ExportAnnotationSummaryArgs = { doc: DocumentId, format: AnnotationSummaryFormat, 
/**
 * The file starts with the document's file name.
 */
includeName: boolean, };

/**
 * What came of exporting an annotation summary (B3-18).
 */
export type AnnotationSummaryOutcome = { "kind": "empty" } | { "kind": "cancelled" } | { "kind": "written", count: number, truncated: boolean, };

/** Limits enforced by the main process (crates/ipc_contract/src/limits.rs). */
export const LIMITS = {
  maxPageCount: 100000,
  maxPageSidePt: 1000000,
  minRenderScale: 0.01,
  maxRenderScale: 64,
  maxRasterSidePx: 8192,
  maxRasterPixels: 16777216,
  maxOutlineItems: 10000,
  maxOutlineDepth: 64,
  maxLinksPerPage: 2000,
  maxUriBytes: 32768,
  maxTextBytes: 1024,
  maxQueryBytes: 1024,
  maxPasswordBytes: 1024,
  maxNewPasswordBytes: 127,
  maxSearchHits: 10000,
  maxQuadsPerHit: 64,
  maxPageTextChars: 100000,
  maxErrorMessageBytes: 1024,
  maxDisplayNameBytes: 1024,
  maxTabs: 20,
  maxRecentFiles: 20,
  maxSensitiveFiles: 1000,
  maxClipboardTextBytes: 16777216,
  maxExportPages: 1000,
  maxBatchFiles: 500,
  maxSplitFiles: 1000,
  maxAnnotationQuads: 1000,
  maxHighlightPages: 100,
  maxNoteTextBytes: 4096,
  maxTextBoxBytes: 4096,
  minTextBoxSize: 4,
  maxTextBoxSize: 288,
  maxInkStrokes: 256,
  maxInkPoints: 20000,
  minAnnotationSidePt: 8,
  maxAnnotationsPerPage: 2000,
  maxFieldsPerPage: 5000,
  maxFieldValueBytes: 16384,
  maxFieldOptions: 1000,
  maxLanguageDataBytes: 67108864,
  maxImportedLanguages: 20,
  maxImportedFonts: 50,
  protocolVersion: 0,
} as const;

/** Binary layout of `render_page` responses (crates/ipc_contract/src/raster.rs). */
export const RASTER = {
  magic: "PDFR",
  headerBytes: 16,
  formatRgba8: 1,
} as const;
